  ('10000000-0000-0000-0000-000000000002', 'Cozy Suburban Family Home', 'Beautifully renovated 4-bedroom home with a large backyard, updated kitchen, and hardwood floors throughout.', 785000, '245 Oakwood Avenue', 'Portland', 'OR', '97201', 'US', 4, 2, 2100, 'house', 'for_sale', true, '00000000-0000-0000-0000-000000000002', ARRAY['https://images.unsplash.com/photo-1571896300421-2a2f5b0a4f1f']),
  ('10000000-0000-0000-0000-000000000003', 'Waterfront Luxury Villa', 'Exclusive waterfront estate with 6 bedrooms, home theater, wine cellar, and resort-style pool.', 3200000, '88 Marina Boulevard', 'Miami', 'FL', '33139', 'US', 6, 5, 5200, 'house', 'for_sale', true, '00000000-0000-0000-0000-000000000001', ARRAY['https://images.unsplash.com/photo-1513694716422-3a1d4b116530']),
  ('10000000-0000-0000-0000-000000000004', 'Downtown Loft Apartment', 'Chic industrial loft with exposed brick walls, high ceilings, and a modern open-concept layout.', 950, '550 Artisan Street, Unit 201', 'Austin', 'TX', '73301', 'US', 2, 2, 1400, 'condo', 'for_rent', false, '00000000-0000-0000-0000-000000000002', ARRAY['https://images.unsplash.com/photo-1502672260264-d3b81d3d5a85']);
INSERT INTO public.blog_posts (id, title, slug, excerpt, content, author_id, published, published_at, image_url) VALUES
